function formQuantity(){document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll("[data-fls-quantity]").forEach(s=>{const a=s.querySelector("[data-fls-quantity-value]");a&&d(s,a.value)})}),document.addEventListener("click",o),document.addEventListener("input",o),document.addEventListener("blur",o);function d(l,s){const a=l.querySelector("[data-fls-quantity-minus]");if(!a)return;(parseInt(s)||1)<=1?a.classList.add("disabled"):a.classList.remove("disabled")}function o(l){const s=l.type,a=l.target,i=a.closest("[data-fls-quantity]");if(!i)return;const e=i.querySelector("[data-fls-quantity-value]");if(!e)return;let t=parseInt(e.value)||1;if(s==="click"){if(a.closest("[data-fls-quantity-plus]")){t++;const n=+e.dataset.flsQuantityMax||1/0;t>n&&(t=n)}else if(a.closest("[data-fls-quantity-minus]")){t--;const n=+e.dataset.flsQuantityMin||1;t<n&&(t=n)}e.value=t,d(i,t)}else if(s==="input"){let n=e.value.replace(/\D/g,"");n=n===""?"1":n,t=parseInt(n)||1;const u=+e.dataset.flsQuantityMax||1/0,c=+e.dataset.flsQuantityMin||1;t>u&&(t=u),t<c&&(t=c),e.value=t,d(i,t)}else if(s==="blur"){let n=e.value.replace(/\D/g,"");t=parseInt(n)||1;const u=+e.dataset.flsQuantityMax||1/0,c=+e.dataset.flsQuantityMin||1;t>u&&(t=u),t<c&&(t=c),e.value=t,d(i,t)}}}document.querySelector("[data-fls-quantity]")&&window.addEventListener("load",formQuantity);
